/* Procedural puzzle library for levels 21–1000.
   ~150 hand-written puzzle families across 10 difficulty tiers. Every level is deterministic (seeded),
   its solution is ≤ 20 lines, and `buildLevels` guarantees no two prompts are identical. */

export type Built = { prompt: string; target: string; hint: string; topic: string; starter?: string; test?: string };
type R = { int: (a: number, b: number) => number; pick: <T>(a: readonly T[]) => T; two: <T>(a: readonly T[]) => [T, T]; nums: (n: number, a: number, b: number) => number[]; uniq: (n: number, a: number, b: number) => number[] };
type Gen = (r: R) => Built;

function rng(seed: number): R {
  let s = seed >>> 0;
  const next = () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const int = (a: number, b: number) => a + Math.floor(next() * (b - a + 1));
  const pick = <T,>(a: readonly T[]) => a[int(0, a.length - 1)];
  const two = <T,>(a: readonly T[]): [T, T] => { const x = pick(a); let y = pick(a); while (y === x) y = pick(a); return [x, y]; };
  const nums = (n: number, a: number, b: number) => Array.from({ length: n }, () => int(a, b));
  const uniq = (n: number, a: number, b: number) => { const o: number[] = []; while (o.length < n) { const v = int(a, b); if (!o.includes(v)) o.push(v); } return o; };
  return { int, pick, two, nums, uniq };
}

const W = ['raven','velvet','cipher','nebula','shadow','signal','winter','silver','lumen','midnight','ember','harbor','lantern','mirror','orchid','pebble','quartz','ripple','tundra','violet','willow','zephyr','comet','marble','saffron','thistle','umbra','vortex','amber','basalt'] as const;
const NAMES = ['Ada','Bo','Cleo','Dax','Eli','Faye','Gus','Hana','Ivo','Juno','Kai','Lena'] as const;
const SENT = ['the tide climbs the cold shore','a quiet star burns above the sea','night tides carry small lights','we map every dark corner','silver fish drift past the pier','the lamp keeps one steady flame','old clocks hum beneath the waves','pale comets cross the harbor'] as const;
const L = (a: number[]) => `[${a.join(', ')}]`;
const SL = (a: readonly string[]) => `[${a.map((x) => `"${x}"`).join(', ')}]`;
const b = (topic: string, prompt: string, target: string, hint: string, extra: Partial<Built> = {}): Built => ({ topic, prompt, target, hint, ...extra });

/* ───────── Tier 1 · output, arithmetic, strings ───────── */
const OPS = [
  { w: 'plus', s: '+', h: 'Use the + operator.' }, { w: 'minus', s: '-', h: 'Use the - operator.' }, { w: 'multiplied by', s: '*', h: 'Multiplication is *.' },
  { w: 'integer-divided by', s: '//', h: '// divides and rounds down.' }, { w: 'modulo', s: '%', h: '% gives the remainder.' },
] as const;
const T1: Gen[] = [
  (r) => { const w = r.pick(W); return b('Output', `Print the word "${w}".`, `print("${w}")`, 'Strings live between quotes.'); },
  (r) => { const [x, y] = r.two(W); return b('Output', `Print "${x}" and "${y}" on one line, separated by a single space.`, `print("${x}", "${y}")`, 'print() puts a space between its arguments.'); },
  (r) => { const x = r.int(12, 60), y = r.int(2, 11), o = r.pick(OPS); return b('Arithmetic', `Print the result of ${x} ${o.w} ${y}.`, `print(${x} ${o.s} ${y})`, o.h); },
  (r) => { const v = r.pick(['signal', 'depth', 'charge', 'glow', 'level']), n = r.int(3, 19), k = r.int(2, 9); return b('Variables', `Create a variable called ${v} equal to ${n}, then print ${v} times ${k}.`, `${v} = ${n}\nprint(${v} * ${k})`, 'Assign first, then use the name.'); },
  (r) => { const w = r.pick(W), k = r.int(2, 5); return b('String repeat', `Print "${w}" repeated ${k} times with nothing in between.`, `print("${w}" * ${k})`, 'Strings can be multiplied by an integer.'); },
  (r) => { const w = r.pick(W); return b('Length', `Print how many characters are in "${w}".`, `print(len("${w}"))`, 'len() measures a string.'); },
  (r) => { const w = r.pick(W), f = r.pick([['uppercase', 'upper'], ['title case', 'title'], ['capitalized form', 'capitalize']]); return b('String methods', `Print "${w}" in ${f[0]}.`, `print("${w}".${f[1]}())`, `Strings have a .${f[1]}() method.`); },
  (r) => { const n = r.pick(NAMES), a = r.int(8, 70); return b('f-strings', `Set name to "${n}" and age to ${a}. Use an f-string to print: ${n} is ${a} years old`, `name = "${n}"\nage = ${a}\nprint(f"{name} is {age} years old")`, 'Put f before the quotes and wrap names in {}.'); },
  (r) => { const w = r.pick(W), k = r.int(2, 4), m = r.pick(['first', 'last']); return b('Slicing', `Print the ${m} ${k} letters of "${w}".`, m === 'first' ? `print("${w}"[:${k}])` : `print("${w}"[-${k}:])`, m === 'first' ? 'Slice from the start: [:k].' : 'Negative slices count from the end.'); },
  (r) => { const [x, y] = r.two(W), j = r.pick(['-', '_', '+', '/']); return b('Concatenation', `Join "${x}" and "${y}" with "${j}" between them and print the result.`, `print("${x}" + "${j}" + "${y}")`, 'Use + to glue strings together.'); },
  (r) => { const x = r.int(2, 40) * 2, y = r.int(1, 30) * 2 + 1; return b('Floats', `Print the average of ${x} and ${y}.`, `print((${x} + ${y}) / 2)`, '/ always produces a float.'); },
  (r) => { const w = r.pick(W), c = r.pick(w.split('')), n = r.pick(['*', '#', '0', '-']); return b('Replace', `Replace every "${c}" in "${w}" with "${n}" and print the result.`, `print("${w}".replace("${c}", "${n}"))`, 'str.replace(old, new) swaps every match.'); },
  (r) => { const [x, y] = r.two([...Array(60).keys()].map((i) => i + 3)); const o = r.pick([['greater than', '>'], ['less than', '<'], ['equal to', '==']]); return b('Booleans', `Print whether ${x} is ${o[0]} ${y} (True or False).`, `print(${x} ${o[1]} ${y})`, 'Comparisons evaluate to True or False.'); },
  (r) => { const w = r.pick(W), c = r.pick(w.split('')); return b('Counting', `Print how many times "${c}" appears in "${w}".`, `print("${w}".count("${c}"))`, 'Strings have a .count() method.'); },
  (r) => { const v = r.uniq(3, 4, 90), f = r.pick([['largest', 'max'], ['smallest', 'min']]); return b('Built-ins', `Print the ${f[0]} of ${v[0]}, ${v[1]} and ${v[2]}.`, `print(${f[1]}(${v.join(', ')}))`, `${f[1]}() accepts several values.`); },
];

/* ───────── Tier 2 · loops and conditions ───────── */
const T2: Gen[] = [
  (r) => { const a = r.int(1, 9), n = a + r.int(3, 7); return b('Loops', `Print every number from ${a} to ${n} inclusive, one per line.`, `for i in range(${a}, ${n + 1}):\n    print(i)`, 'range stops before its last value.'); },
  (r) => { const n = r.int(4, 12); return b('Loops', `Count down from ${n} to 1, one number per line.`, `for i in range(${n}, 0, -1):\n    print(i)`, 'A negative step counts down.'); },
  (r) => { const k = r.int(2, 9), n = k * r.int(3, 6) + r.int(0, k - 1); return b('Loops', `Print the multiples of ${k} that are at most ${n}, one per line.`, `for i in range(${k}, ${n + 1}, ${k}):\n    print(i)`, 'Use range(start, stop, step).'); },
  (r) => { const n = r.int(8, 40); return b('Accumulators', `Use a loop to add the numbers 1 through ${n} and print the total.`, `total = 0\nfor i in range(1, ${n + 1}):\n    total += i\nprint(total)`, 'Keep a running total outside the loop.'); },
  (r) => { const n = r.int(3, 8); return b('Loops', `For each number from 1 to ${n}, print the number, a space, and its square.`, `for i in range(1, ${n + 1}):\n    print(i, i * i)`, 'print() accepts several values.'); },
  (r) => { const n = r.int(2, 99); return b('Conditions', `Print "even" if ${n} is even, otherwise print "odd".`, `n = ${n}\nif n % 2 == 0:\n    print("even")\nelse:\n    print("odd")`, 'Check n % 2.'); },
  (r) => { const a = r.int(2, 4), n = r.int(7, 15); return b('Conditions', `For each number from 1 to ${n}, print "Fizz" when it is divisible by ${a}, otherwise print the number.`, `for i in range(1, ${n + 1}):\n    if i % ${a} == 0:\n        print("Fizz")\n    else:\n        print(i)`, 'Test divisibility first inside the loop.'); },
  (r) => { const n = r.int(3, 7), ch = r.pick(['*', '#', '+', 'o']); return b('Patterns', `Print a triangle of "${ch}" with ${n} rows, where row i has i characters.`, `for i in range(1, ${n + 1}):\n    print("${ch}" * i)`, 'Multiply the character by the row number.'); },
  (r) => { const n = r.int(3, 7), ch = r.pick(['*', '#', '+', 'o']); return b('Patterns', `Print an upside-down triangle of "${ch}": ${n} characters on the first row, then one fewer each row, down to 1.`, `for i in range(${n}, 0, -1):\n    print("${ch}" * i)`, 'Loop downwards.'); },
  (r) => { let n = r.int(20, 200); return b('While loops', `Starting from ${n}, print the value, halve it with integer division, and repeat while it is above 0.`, `n = ${n}\nwhile n > 0:\n    print(n)\n    n //= 2`, 'A while loop runs until its condition fails.'); },
  (r) => { const w = r.pick(W); return b('Loops', `Print each letter of "${w}" on its own line.`, `for ch in "${w}":\n    print(ch)`, 'Strings are iterable.'); },
  (r) => { const t = r.int(40, 80), s = r.int(30, 95); return b('Conditions', `A score of ${t} or more passes. Print "pass" for a score of ${s}, otherwise print "retry".`, `score = ${s}\nif score >= ${t}:\n    print("pass")\nelse:\n    print("retry")`, 'Use >= for "or more".'); },
  (r) => { const n = r.int(4, 9); return b('Accumulators', `Use a loop to multiply the numbers 1 through ${n} together and print the product.`, `product = 1\nfor i in range(1, ${n + 1}):\n    product *= i\nprint(product)`, 'Start the product at 1, not 0.'); },
  (r) => { const n = r.int(10, 40); return b('Accumulators', `Print the sum of the even numbers from 1 to ${n}.`, `total = 0\nfor i in range(1, ${n + 1}):\n    if i % 2 == 0:\n        total += i\nprint(total)`, 'Add only when i % 2 == 0.'); },
  (r) => { const k = r.int(4, 9); return b('Break', `Print 1, 2, 3, … one per line, stopping just before the first multiple of ${k}.`, `for i in range(1, 100):\n    if i % ${k} == 0:\n        break\n    print(i)`, 'break leaves the loop early.'); },
  (r) => { const n = r.int(2, 12); return b('Tables', `Print the first 5 rows of the ${n} times table in the form "${n} x 1 = ${n}".`, `for i in range(1, 6):\n    print(f"${n} x {i} = {${n} * i}")`, 'An f-string can hold expressions.'); },
];

/* ───────── Tier 3 · functions and lists ───────── */
const T3: Gen[] = [
  (r) => { const k = r.int(2, 4), n = r.int(2, 9); const nm = k === 2 ? 'square' : k === 3 ? 'cube' : 'fourth'; return b('Functions', `Define a function ${nm}(x) that returns x to the power of ${k}, then print ${nm}(${n}).`, `def ${nm}(x):\n    return x ** ${k}\nprint(${nm}(${n}))`, 'def, a parameter, return.'); },
  (r) => { const w = r.pick(W), p = r.pick(['!', '?', '.', '...']); return b('Default arguments', `Define greet(name, mark="!") that returns "Hello, " + name + mark. Print greet("${w}"${p === '!' ? '' : `, "${p}"`}).`, `def greet(name, mark="!"):\n    return "Hello, " + name + mark\nprint(greet("${w}"${p === '!' ? '' : `, "${p}"`}))`, 'A default value goes after = in the signature.'); },
  (r) => { const [x, y] = r.two([...Array(90).keys()].map((i) => i + 5)); return b('Functions', `Define bigger(a, b) that returns the larger value, then print bigger(${x}, ${y}).`, `def bigger(a, b):\n    if a > b:\n        return a\n    return b\nprint(bigger(${x}, ${y}))`, 'Compare, then return one of them.'); },
  (r) => { const w = r.pick(W); return b('Functions', `Define count_vowels(text) that returns how many of a, e, i, o, u it contains, then print count_vowels("${w}").`, `def count_vowels(text):\n    total = 0\n    for ch in text:\n        if ch in "aeiou":\n            total += 1\n    return total\nprint(count_vowels("${w}"))`, 'Check membership with "in".'); },
  (r) => { const a = r.nums(r.int(3, 5), 2, 40); return b('Lists', `Print the sum of the list ${L(a)}.`, `print(sum(${L(a)}))`, 'sum() adds a list.'); },
  (r) => { const a = r.uniq(r.int(4, 6), 3, 90); return b('Lists', `For the list ${L(a)}, print its largest and smallest values on one line, separated by a space.`, `nums = ${L(a)}\nprint(max(nums), min(nums))`, 'Call max and min.'); },
  (r) => { const a = r.nums(3, 1, 30), k = r.int(31, 60); return b('List methods', `Start with ${L(a)}, append ${k}, then print the list.`, `nums = ${L(a)}\nnums.append(${k})\nprint(nums)`, '.append() adds one item at the end.'); },
  (r) => { const a = r.nums(8, 1, 50), i = r.int(0, 3), j = r.int(5, 8); return b('Slicing', `Print the slice of ${L(a)} from index ${i} up to, but not including, index ${j}.`, `print(${L(a)}[${i}:${j}])`, 'list[start:stop].'); },
  (r) => { const a = r.nums(r.int(4, 7), 1, 99); return b('Slicing', `Print the list ${L(a)} in reverse order.`, `print(${L(a)}[::-1])`, 'A step of -1 walks backwards.'); },
  (r) => { const a = r.uniq(6, 1, 80), i = r.int(0, 5); return b('List methods', `Print the index of ${a[i]} in ${L(a)}.`, `print(${L(a)}.index(${a[i]}))`, '.index() finds a value.'); },
  (r) => { const k = r.int(2, 9), n = r.int(4, 7); return b('Functions', `Define multiples(k, n) that returns a list of the first n multiples of k starting at k, then print multiples(${k}, ${n}).`, `def multiples(k, n):\n    result = []\n    for i in range(1, n + 1):\n        result.append(k * i)\n    return result\nprint(multiples(${k}, ${n}))`, 'Build a list in a loop, then return it.'); },
  (r) => { const a = r.nums(r.int(5, 7), 1, 99); return b('Sorting', `Print ${L(a)} sorted from smallest to largest.`, `print(sorted(${L(a)}))`, 'sorted() returns a new list.'); },
  (r) => { const n = r.int(3, 5), a = r.nums(n, 1, 20).map((x) => x + 1); const s = a.reduce((p, c) => p + c, 0); const adj = (n - (s % n)) % n; a[0] += adj; return b('Averages', `Print the average of ${L(a)} rounded to 2 decimal places.`, `nums = ${L(a)}\nprint(round(sum(nums) / len(nums), 2))`, 'round(value, digits).'); },
  (r) => { const w = r.pick(W); return b('Functions', `Define shout(text) that returns the text in uppercase followed by "!". Print shout("${w}").`, `def shout(text):\n    return text.upper() + "!"\nprint(shout("${w}"))`, 'Chain a method call and +.'); },
  (r) => { const n = r.int(4, 8), p = r.int(2, 3); return b('Lists', `Build a list of the first ${n} ${p === 2 ? 'square' : 'cube'} numbers (starting from 1) with a loop and print it.`, `result = []\nfor i in range(1, ${n + 1}):\n    result.append(i ** ${p})\nprint(result)`, 'Append inside the loop.'); },
];

/* ───────── Tier 4 · dicts, tuples, enumerate, zip ───────── */
const T4: Gen[] = [
  (r) => { const ks = r.two(W), vs = r.nums(2, 1, 99), q = r.int(0, 1); return b('Dictionaries', `Make a dictionary with ${ks[0]} → ${vs[0]} and ${ks[1]} → ${vs[1]}. Print the value stored for "${ks[q]}".`, `d = {"${ks[0]}": ${vs[0]}, "${ks[1]}": ${vs[1]}}\nprint(d["${ks[q]}"])`, 'Index a dict with its key.'); },
  (r) => { const ks = r.two(W), vs = r.nums(2, 1, 50), nk = r.pick(W.filter((w) => !ks.includes(w))), nv = r.int(51, 99); return b('Dictionaries', `Start with {"${ks[0]}": ${vs[0]}, "${ks[1]}": ${vs[1]}}, add "${nk}" with value ${nv}, and print the dictionary.`, `d = {"${ks[0]}": ${vs[0]}, "${ks[1]}": ${vs[1]}}\nd["${nk}"] = ${nv}\nprint(d)`, 'Assign to a new key to add it.'); },
  (r) => { const ks = r.uniq(3, 0, W.length - 1).map((i) => W[i]), vs = r.nums(3, 1, 20); return b('Dictionaries', `Loop over {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}} and print each pair as key: value.`, `d = {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}}\nfor k, v in d.items():\n    print(f"{k}: {v}")`, '.items() yields key and value.'); },
  (r) => { const ws = r.uniq(3, 0, W.length - 1).map((i) => W[i]); return b('enumerate', `Print ${SL(ws)} as a numbered list starting at 1, formatted like "1. word".`, `for i, w in enumerate(${SL(ws)}, 1):\n    print(f"{i}. {w}")`, 'enumerate(items, 1) starts counting at 1.'); },
  (r) => { const ws = r.uniq(3, 0, W.length - 1).map((i) => W[i]), ns = r.nums(3, 1, 9); return b('zip', `Pair ${SL(ws)} with ${L(ns)} using zip and print each pair on a line as "word number".`, `for w, n in zip(${SL(ws)}, ${L(ns)}):\n    print(w, n)`, 'zip walks two lists together.'); },
  (r) => { const k = r.pick(W), d = r.int(0, 5); return b('Dictionaries', `Using d = {"${W[0]}": 1}, print d.get("${k === W[0] ? 'missing' : k}", ${d}) so the default is shown for a missing key.`, `d = {"${W[0]}": 1}\nprint(d.get("${k === W[0] ? 'missing' : k}", ${d}))`, '.get(key, default) never raises.'); },
  (r) => { const [x, y] = r.two(W); return b('Tuples', `Set a = "${x}" and b = "${y}", swap them in one line using tuple unpacking, then print a and b on one line.`, `a = "${x}"\nb = "${y}"\na, b = b, a\nprint(a, b)`, 'a, b = b, a'); },
  (r) => { const s = r.pick(SENT); return b('Splitting', `Split "${s}" into words and print how many words there are.`, `print(len("${s}".split()))`, '.split() cuts on whitespace.'); },
  (r) => { const ws = r.uniq(r.int(3, 4), 0, W.length - 1).map((i) => W[i]), j = r.pick([', ', ' | ', ' - ', '/']); return b('Joining', `Join ${SL(ws)} with "${j}" between the items and print the result.`, `print("${j}".join(${SL(ws)}))`, 'The separator calls .join(list).'); },
  (r) => { const s = r.pick(SENT); return b('String methods', `Print "${s}" with every word capitalized.`, `print("${s}".title())`, '.title() capitalizes each word.'); },
  (r) => { const a = r.uniq(5, 1, 60), x = r.int(0, 4); return b('List methods', `Start with ${L(a)}, remove the value ${a[x]}, and print the list.`, `nums = ${L(a)}\nnums.remove(${a[x]})\nprint(nums)`, '.remove() deletes the first match.'); },
  (r) => { const ks = r.uniq(3, 0, W.length - 1).map((i) => W[i]), vs = r.nums(3, 2, 40); return b('Dictionaries', `Print the sum of the values in {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}}.`, `d = {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}}\nprint(sum(d.values()))`, '.values() lists just the values.'); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]), x = r.pick(W); return b('Membership', `Print whether "${x}" is in ${SL(ws)} (True or False).`, `print("${x}" in ${SL(ws)})`, 'in tests membership.'); },
  (r) => { const m = [r.nums(3, 1, 9), r.nums(3, 1, 9), r.nums(3, 1, 9)], i = r.int(0, 2), j = r.int(0, 2); return b('Nested lists', `Given grid = [${m.map(L).join(', ')}], print the value in row ${i}, column ${j} (counting from 0).`, `grid = [${m.map(L).join(', ')}]\nprint(grid[${i}][${j}])`, 'Index twice: grid[row][col].'); },
  (r) => { const ks = r.uniq(3, 0, W.length - 1).map((i) => W[i]), vs = r.nums(3, 1, 9); return b('Dictionaries', `Given {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}}, print its keys in alphabetical order as a list.`, `d = {${ks.map((k, i) => `"${k}": ${vs[i]}`).join(', ')}}\nprint(sorted(d))`, 'sorted() on a dict sorts its keys.'); },
];

/* ───────── Tier 5 · comprehensions, sets, sorting keys ───────── */
const T5: Gen[] = [
  (r) => { const n = r.int(4, 9), p = r.int(2, 3); return b('Comprehensions', `Use a list comprehension to print the ${p === 2 ? 'squares' : 'cubes'} of 1 through ${n}.`, `print([x ** ${p} for x in range(1, ${n + 1})])`, '[expr for x in range(...)]'); },
  (r) => { const n = r.int(10, 30), m = r.pick([2, 3, 5]); return b('Filtering', `Use a comprehension to print the numbers from 1 to ${n} that are divisible by ${m}.`, `print([x for x in range(1, ${n + 1}) if x % ${m} == 0])`, 'Add an if clause at the end.'); },
  (r) => { const ws = r.uniq(5, 0, W.length - 1).map((i) => W[i]), k = r.int(5, 6); return b('Filtering', `From ${SL(ws)}, print the words longer than ${k - 1} letters as a list.`, `words = ${SL(ws)}\nprint([w for w in words if len(w) > ${k - 1}])`, 'Filter on len(w).'); },
  (r) => { const a = r.nums(8, 1, 9); return b('Sets', `Print the unique values of ${L(a)} as a sorted list.`, `print(sorted(set(${L(a)})))`, 'set() removes duplicates.'); },
  (r) => { const a = r.uniq(5, 1, 15), c = r.uniq(5, 1, 15), op = r.pick([['common to both', '&'], ['in either', '|'], ['only in the first', '-']]); return b('Set operations', `Print the values ${op[0]} of ${L(a)} and ${L(c)} as a sorted list.`, `a = set(${L(a)})\nb = set(${L(c)})\nprint(sorted(a ${op[1]} b))`, `Sets support ${op[1]}.`); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]); return b('Sorting keys', `Print ${SL(ws)} sorted by word length, shortest first (keep original order for ties).`, `print(sorted(${SL(ws)}, key=len))`, 'sorted accepts key=len.'); },
  (r) => { const a = r.uniq(6, 1, 99); return b('Sorting', `Print ${L(a)} sorted from largest to smallest.`, `print(sorted(${L(a)}, reverse=True))`, 'reverse=True flips the order.'); },
  (r) => { const ws = r.uniq(3, 0, W.length - 1).map((i) => W[i]); return b('Dict comprehensions', `Use a dictionary comprehension mapping each word in ${SL(ws)} to its length, then print it.`, `print({w: len(w) for w in ${SL(ws)}})`, '{key: value for item in items}'); },
  (r) => { const a = r.nums(5, 3, 30), k = r.int(4, 12), q = r.pick([['all', 'greater than', '>'], ['any', 'greater than', '>'], ['all', 'less than', '<']]); return b('any / all', `Print whether ${q[0] === 'all' ? 'all' : 'any'} of the values in ${L(a)} are ${q[1]} ${k}.`, `print(${q[0]}(x ${q[2]} ${k} for x in ${L(a)}))`, `${q[0]}() takes a generator of booleans.`); },
  (r) => { const k = r.int(2, 7), n = r.int(30, 90); return b('Comprehensions', `Print the sum of all multiples of ${k} below ${n}.`, `print(sum(x for x in range(${n}) if x % ${k} == 0))`, 'Feed a generator expression to sum().'); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]), f = r.pick([['longest', 'max'], ['shortest', 'min']]); return b('Key functions', `Print the ${f[0]} word in ${SL(ws)} (the first one wins a tie).`, `print(${f[1]}(${SL(ws)}, key=len))`, `${f[1]}(items, key=len)`); },
  (r) => { const a = r.nums(4, 1, 9), k = r.int(2, 6); return b('map and lambda', `Use map with a lambda to multiply every value of ${L(a)} by ${k}, then print the result as a list.`, `print(list(map(lambda x: x * ${k}, ${L(a)})))`, 'map returns an iterator; wrap in list().'); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]); return b('Comprehensions', `Print a string made from the first letter of each word in ${SL(ws)}.`, `print("".join(w[0] for w in ${SL(ws)}))`, 'Join a generator of letters.'); },
  (r) => { const ks = r.uniq(3, 0, W.length - 1).map((i) => W[i]), vs = r.nums(3, 1, 9); return b('zip and dict', `Build a dictionary from the keys ${SL(ks)} and values ${L(vs)} using zip, then print it.`, `print(dict(zip(${SL(ks)}, ${L(vs)})))`, 'dict(zip(keys, values))'); },
  (r) => { const g = [r.nums(2, 1, 9), r.nums(3, 1, 9), r.nums(2, 1, 9)]; return b('Flattening', `Flatten [${g.map(L).join(', ')}] into a single list with a comprehension and print it.`, `print([x for row in [${g.map(L).join(', ')}] for x in row])`, 'Two for clauses, outer loop first.'); },
];

/* ───────── Tier 6 · strings, nested loops, patterns ───────── */
const T6: Gen[] = [
  (r) => { const w = r.pick(W); return b('Frequency maps', `Count each character in "${w}" and print the dictionary (characters in order of first appearance).`, `counts = {}\nfor ch in "${w}":\n    counts[ch] = counts.get(ch, 0) + 1\nprint(counts)`, 'dict.get(ch, 0) + 1'); },
  (r) => { const s = r.pick(SENT); return b('Counting', `Print how many vowels (a, e, i, o, u) are in "${s}".`, `print(sum(1 for ch in "${s}" if ch in "aeiou"))`, 'Count characters that are in "aeiou".'); },
  (r) => { const w = r.pick([...W, 'level', 'radar', 'noon', 'civic', 'refer']); return b('Palindromes', `Print True if "${w}" reads the same forwards and backwards, otherwise False.`, `w = "${w}"\nprint(w == w[::-1])`, 'Compare with the reversed slice.'); },
  (r) => { const s = r.pick(SENT); return b('Words', `Print "${s}" with each word's first letter capitalized, using split and join.`, `words = "${s}".split()\nprint(" ".join(w.capitalize() for w in words))`, 'Split, transform each word, join.'); },
  (r) => { const s = r.pick(SENT); return b('Words', `Reverse the letters of every word in "${s}", keeping the word order, and print the sentence.`, `words = "${s}".split()\nprint(" ".join(w[::-1] for w in words))`, 'Reverse each word, not the sentence.'); },
  (r) => { const w = r.pick(W); return b('Frequency maps', `Print the most frequent letter in "${w}" (alphabetically first on a tie).`, `w = "${w}"\nprint(max(sorted(set(w)), key=w.count))`, 'Sort first so ties resolve alphabetically.'); },
  (r) => { const w = r.pick(W), k = r.int(1, 5); return b('Ciphers', `Shift every letter of "${w}" forward by ${k} places (wrapping z to a) and print the result.`, `w = "${w}"\nout = ""\nfor ch in w:\n    out += chr((ord(ch) - 97 + ${k}) % 26 + 97)\nprint(out)`, 'ord() and chr() convert letters and numbers.'); },
  (r) => { const rows = r.int(2, 4), cols = r.int(3, 6), ch = r.pick(['#', '*', '@', 'o']); return b('Nested loops', `Print a rectangle of "${ch}" with ${rows} rows and ${cols} columns.`, `for _ in range(${rows}):\n    print("${ch}" * ${cols})`, 'One print per row.'); },
  (r) => { const rows = r.int(3, 5), cols = r.int(4, 7); return b('Nested loops', `Print a ${rows}-row, ${cols}-column checkerboard of "#" and "." where the top-left cell is "#".`, `for r in range(${rows}):\n    row = ""\n    for c in range(${cols}):\n        row += "#" if (r + c) % 2 == 0 else "."\n    print(row)`, 'Alternate on (row + col) % 2.'); },
  (r) => { const n = r.int(3, 5); return b('Nested loops', `Print a ${n}×${n} multiplication grid: row i holds i×1 … i×${n} separated by spaces.`, `for i in range(1, ${n + 1}):\n    print(" ".join(str(i * j) for j in range(1, ${n + 1})))`, 'Build each row with join.'); },
  (r) => { const n = r.int(3, 6); return b('Patterns', `Print a right-aligned staircase of "#" with ${n} steps, padding each row with spaces on the left to width ${n}.`, `for i in range(1, ${n + 1}):\n    print(" " * (${n} - i) + "#" * i)`, 'Spaces first, then hashes.'); },
  (r) => { const n = r.int(1000, 99999); return b('Digits', `Print the sum of the digits of ${n}.`, `print(sum(int(c) for c in str(${n})))`, 'Convert to str, loop, convert back.'); },
  (r) => { const s = r.pick(SENT), k = r.int(3, 5); return b('Words', `Print how many words in "${s}" are longer than ${k} letters.`, `print(sum(1 for w in "${s}".split() if len(w) > ${k}))`, 'Count words with len(w) > k.'); },
  (r) => { const w = r.pick(W); return b('String methods', `Print "${w}" with all of its vowels removed.`, `print("".join(ch for ch in "${w}" if ch not in "aeiou"))`, 'Keep only characters not in "aeiou".'); },
  (r) => { const ws = r.uniq(3, 0, W.length - 1).map((i) => W[i]); return b('Acronyms', `Print the uppercase acronym formed by the first letters of ${SL(ws)}.`, `print("".join(w[0] for w in ${SL(ws)}).upper())`, 'First letters, joined, uppercased.'); },
  (r) => { const [x, y] = r.two(['listen', 'silent', 'enlist', 'stone', 'notes', 'onset', 'raven', 'cipher', 'lumen', 'signal', 'night', 'thing']); return b('Anagrams', `Print True if "${x}" and "${y}" contain exactly the same letters, otherwise False.`, `print(sorted("${x}") == sorted("${y}"))`, 'Compare sorted letters.'); },
];

/* ───────── Tier 7 · recursion and number theory ───────── */
const T7: Gen[] = [
  (r) => { const n = r.int(4, 9); return b('Recursion', `Write a recursive function factorial(n) and print factorial(${n}).`, `def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\nprint(factorial(${n}))`, 'The base case stops the recursion.'); },
  (r) => { const n = r.int(6, 15); return b('Recursion', `Write a recursive fib(n) with fib(0) = 0 and fib(1) = 1, then print fib(${n}).`, `def fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\nprint(fib(${n}))`, 'Two base cases, two recursive calls.'); },
  (r) => { const g = r.int(2, 9), x = g * r.int(2, 9), y = g * r.int(2, 9) + g; return b('Euclid', `Print the greatest common divisor of ${x} and ${y}, using Euclid's algorithm.`, `a, b = ${x}, ${y}\nwhile b:\n    a, b = b, a % b\nprint(a)`, 'Repeat (a, b) = (b, a % b) until b is 0.'); },
  (r) => { const x = r.int(2, 9), y = r.int(3, 12); return b('Euclid', `Print the least common multiple of ${x} and ${y}.`, `a, b = ${x}, ${y}\ng = a\nh = b\nwhile h:\n    g, h = h, g % h\nprint(a * b // g)`, 'lcm = a * b // gcd.'); },
  (r) => { const n = r.int(10, 120); return b('Primes', `Define is_prime(n) and print is_prime(${n}).`, `def is_prime(n):\n    if n < 2:\n        return False\n    for i in range(2, int(n ** 0.5) + 1):\n        if n % i == 0:\n            return False\n    return True\nprint(is_prime(${n}))`, 'Trial division up to √n.'); },
  (r) => { const n = r.int(15, 50); return b('Primes', `Print the list of prime numbers below ${n}.`, `primes = []\nfor n in range(2, ${n}):\n    if all(n % i for i in range(2, int(n ** 0.5) + 1)):\n        primes.append(n)\nprint(primes)`, 'all() over trial divisors.'); },
  (r) => { const n = r.int(100, 99999); return b('Recursion', `Write a recursive function digit_sum(n) and print digit_sum(${n}).`, `def digit_sum(n):\n    if n < 10:\n        return n\n    return n % 10 + digit_sum(n // 10)\nprint(digit_sum(${n}))`, 'Peel off n % 10 each call.'); },
  (r) => { const x = r.int(2, 5), e = r.int(3, 8); return b('Recursion', `Write a recursive power(base, exp) without using ** and print power(${x}, ${e}).`, `def power(base, exp):\n    if exp == 0:\n        return 1\n    return base * power(base, exp - 1)\nprint(power(${x}, ${e}))`, 'power(b, 0) is 1.'); },
  (r) => { const n = r.int(6, 60); return b('Collatz', `Starting from ${n}, halve even numbers and map odd numbers to 3n+1 until you reach 1. Print how many steps it takes.`, `n = ${n}\nsteps = 0\nwhile n != 1:\n    n = n // 2 if n % 2 == 0 else 3 * n + 1\n    steps += 1\nprint(steps)`, 'Count loop iterations.'); },
  (r) => { const w = r.pick(W); return b('Recursion', `Write a recursive function rev(s) that reverses a string without slicing, and print rev("${w}").`, `def rev(s):\n    if len(s) <= 1:\n        return s\n    return rev(s[1:]) + s[0]\nprint(rev("${w}"))`, 'Reverse the rest, then add the first letter.'); },
  (r) => { const a = r.nums(r.int(4, 6), 1, 20); return b('Recursion', `Write a recursive function total(items) that sums a list, and print total(${L(a)}).`, `def total(items):\n    if not items:\n        return 0\n    return items[0] + total(items[1:])\nprint(total(${L(a)}))`, 'An empty list sums to 0.'); },
  (r) => { const n = r.int(5, 200); return b('Binary', `Print the binary digits of ${n} without using bin() or format().`, `n = ${n}\nbits = ""\nwhile n > 0:\n    bits = str(n % 2) + bits\n    n //= 2\nprint(bits)`, 'Collect n % 2 and halve, building the string leftward.'); },
  (r) => { const n = r.pick([6, 28, 12, 20, 496, 8128, 18, 30, 24, 36]); return b('Divisors', `Print True if ${n} equals the sum of its proper divisors (all divisors except itself), otherwise False.`, `n = ${n}\nprint(sum(i for i in range(1, n) if n % i == 0) == n)`, 'Sum i where n % i == 0.'); },
  (r) => { const n = r.int(12, 360); return b('Divisors', `Print how many positive divisors ${n} has.`, `n = ${n}\nprint(sum(1 for i in range(1, n + 1) if n % i == 0))`, 'Count i with n % i == 0.'); },
  (r) => { const n = r.int(6, 40); return b('Recursion', `Write a recursive triangular(n) where triangular(1) = 1 and triangular(n) = n + triangular(n - 1), and print triangular(${n}).`, `def triangular(n):\n    if n == 1:\n        return 1\n    return n + triangular(n - 1)\nprint(triangular(${n}))`, 'Base case at 1.'); },
  (r) => { const n = r.int(100, 99999); return b('Digits', `Repeatedly add the digits of ${n} until a single digit remains, and print it.`, `n = ${n}\nwhile n > 9:\n    n = sum(int(c) for c in str(n))\nprint(n)`, 'Loop while n has more than one digit.'); },
];

/* ───────── Tier 8 · classes, errors, generators, stacks ───────── */
const T8: Gen[] = [
  (r) => { const s = r.int(2, 12); return b('Classes', `Define a class Square with an attribute side and a method area() that returns side squared. Print Square(${s}).area().`, `class Square:\n    def __init__(self, side):\n        self.side = side\n    def area(self):\n        return self.side ** 2\nprint(Square(${s}).area())`, '__init__ stores attributes on self.'); },
  (r) => { const n = r.pick(NAMES), sd = r.pick(['purrs', 'barks', 'chirps', 'hums', 'glows']); return b('Classes', `Define a class Pet with a name and a method speak() returning "<name> ${sd}". Print Pet("${n}").speak().`, `class Pet:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        return self.name + " ${sd}"\nprint(Pet("${n}").speak())`, 'Use self.name inside methods.'); },
  (r) => { const s = r.int(50, 200), d = r.int(10, 40), w = r.int(5, 30); return b('Classes', `Create an Account class starting with a balance. deposit(x) adds and withdraw(x) subtracts. Start at ${s}, deposit ${d}, withdraw ${w}, then print the balance.`, `class Account:\n    def __init__(self, balance):\n        self.balance = balance\n    def deposit(self, x):\n        self.balance += x\n    def withdraw(self, x):\n        self.balance -= x\na = Account(${s})\na.deposit(${d})\na.withdraw(${w})\nprint(a.balance)`, 'Methods mutate self.balance.'); },
  (r) => { const x = r.int(5, 50), y = r.pick([0, 0, 2, 4, 5]); return b('Exceptions', `Try to print ${x} // ${y}. If it raises ZeroDivisionError, print "cannot divide" instead.`, `try:\n    print(${x} // ${y})\nexcept ZeroDivisionError:\n    print("cannot divide")`, 'try / except ZeroDivisionError.'); },
  (r) => { const v = r.pick(['12', 'abc', '7', 'x9', '40', '3.5']); return b('Exceptions', `Convert "${v}" with int(). Print the number if it works, otherwise print "invalid".`, `try:\n    print(int("${v}"))\nexcept ValueError:\n    print("invalid")`, 'int() raises ValueError on bad text.'); },
  (r) => { const n = r.int(3, 7), p = r.int(2, 3); return b('Generators', `Write a generator function powers(n) that yields 1**${p}, 2**${p}, … n**${p}. Print list(powers(${n})).`, `def powers(n):\n    for i in range(1, n + 1):\n        yield i ** ${p}\nprint(list(powers(${n})))`, 'yield produces values lazily.'); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]); return b('Stacks', `Use a list as a stack: push ${SL(ws)} in order, pop once, then print the remaining stack.`, `stack = []\nfor w in ${SL(ws)}:\n    stack.append(w)\nstack.pop()\nprint(stack)`, '.append pushes, .pop() removes the last item.'); },
  (r) => { const ws = r.uniq(4, 0, W.length - 1).map((i) => W[i]); return b('Queues', `Use a list as a queue holding ${SL(ws)}. Dequeue from the front twice and print each removed item on its own line.`, `queue = ${SL(ws)}\nprint(queue.pop(0))\nprint(queue.pop(0))`, 'pop(0) removes the first item.'); },
  (r) => { const sd = r.pick(['woof', 'meow', 'hoot', 'chirp']); return b('Inheritance', `Define Animal with speak() returning "...". Define Dog(Animal) overriding speak() to return "${sd}". Print Animal().speak() and Dog().speak() on separate lines.`, `class Animal:\n    def speak(self):\n        return "..."\nclass Dog(Animal):\n    def speak(self):\n        return "${sd}"\nprint(Animal().speak())\nprint(Dog().speak())`, 'class Child(Parent) overrides methods.'); },
  (r) => { const c = r.pick([0, 20, 37, 100, -10, 25, 60]); return b('Classes', `Define a class Temp with celsius and a method fahrenheit() returning celsius * 9 / 5 + 32. Print Temp(${c}).fahrenheit().`, `class Temp:\n    def __init__(self, celsius):\n        self.celsius = celsius\n    def fahrenheit(self):\n        return self.celsius * 9 / 5 + 32\nprint(Temp(${c}).fahrenheit())`, 'Return a computed value.'); },
  (r) => { const ws = r.uniq(5, 0, W.length - 1).map((i) => W[i]); return b('Grouping', `Group ${SL(ws)} into a dictionary keyed by word length, each value a list of words in original order. Print the dictionary.`, `groups = {}\nfor w in ${SL(ws)}:\n    groups.setdefault(len(w), []).append(w)\nprint(groups)`, '.setdefault creates the list on first use.'); },
  (r) => { const a = r.nums(3, 0, 9), i = r.int(3, 8); return b('Exceptions', `Print ${L(a)}[${i}]. If that raises IndexError, print "out of range" instead.`, `try:\n    print(${L(a)}[${i}])\nexcept IndexError:\n    print("out of range")`, 'Catch IndexError.'); },
  (r) => { const ws = r.uniq(3, 0, W.length - 1).map((i) => W[i]), ns = r.uniq(3, 1, 9); const ps = ws.map((w, i) => `("${w}", ${ns[i]})`); return b('Sorting keys', `Sort the pairs [${ps.join(', ')}] by their number, largest first, and print the words in that order separated by spaces.`, `pairs = [${ps.join(', ')}]\nordered = sorted(pairs, key=lambda p: p[1], reverse=True)\nprint(" ".join(p[0] for p in ordered))`, 'key=lambda p: p[1]'); },
  (r) => { const k = r.int(1, 5), n = r.int(3, 8); return b('Classes', `Define a Counter class with count starting at 0 and a method tick() that adds ${k}. Call tick() ${n} times, then print count.`, `class Counter:\n    def __init__(self):\n        self.count = 0\n    def tick(self):\n        self.count += ${k}\nc = Counter()\nfor _ in range(${n}):\n    c.tick()\nprint(c.count)`, 'State lives on self.'); },
  (r) => { const a = r.int(1, 9), c = r.int(10, 99); return b('Formatting', `Print ${a} and ${c} right-aligned in columns of width 6, one per line, using f-string format specs.`, `print(f"{${a}:>6}")\nprint(f"{${c}:>6}")`, '{value:>6} right-aligns in width 6.'); },
];

/* ───────── Tier 9 · classic algorithms ───────── */
const sorted9 = (r: R, n: number) => r.uniq(n, 1, 90).sort((x, y) => x - y);
const T9: Gen[] = [
  (r) => { const a = sorted9(r, 8), t = r.pick([a[r.int(0, 7)], a[r.int(0, 7)], r.int(91, 99)]); return b('Binary search', `Using binary search on the sorted list ${L(a)}, print the index of ${t}, or -1 if it is absent.`, `nums = ${L(a)}\nlo, hi = 0, len(nums) - 1\nans = -1\nwhile lo <= hi:\n    mid = (lo + hi) // 2\n    if nums[mid] == ${t}:\n        ans = mid\n        break\n    if nums[mid] < ${t}:\n        lo = mid + 1\n    else:\n        hi = mid - 1\nprint(ans)`, 'Halve the search range each step.'); },
  (r) => { const a = r.uniq(6, 1, 60); return b('Sorting', `Sort ${L(a)} with bubble sort and print the sorted list.`, `nums = ${L(a)}\nfor i in range(len(nums)):\n    for j in range(len(nums) - 1 - i):\n        if nums[j] > nums[j + 1]:\n            nums[j], nums[j + 1] = nums[j + 1], nums[j]\nprint(nums)`, 'Swap neighbours that are out of order.'); },
  (r) => { const a = r.uniq(6, 1, 30), i = r.int(0, 2), j = r.int(3, 5), t = a[i] + a[j]; return b('Two sum', `Scanning i then j (with i < j), print the first pair of indices "i j" in ${L(a)} whose values add up to ${t}.`, `nums = ${L(a)}\nfound = False\nfor i in range(len(nums)):\n    for j in range(i + 1, len(nums)):\n        if not found and nums[i] + nums[j] == ${t}:\n            print(i, j)\n            found = True`, 'Nested loops over pairs.'); },
  (r) => { const s = r.pick(['aaabcc', 'zzzyxx', 'aabbbbc', 'mmmmnoo', 'abccc', 'ppqqqrrrr', 'xyyyzz']); return b('Run-length encoding', `Run-length encode "${s}" as letter+count pairs (for example "aab" → "a2b1") and print it.`, `s = "${s}"\nout = ""\ni = 0\nwhile i < len(s):\n    j = i\n    while j < len(s) and s[j] == s[i]:\n        j += 1\n    out += s[i] + str(j - i)\n    i = j\nprint(out)`, 'Count each run, then jump past it.'); },
  (r) => { const m = [r.nums(3, 1, 9), r.nums(3, 1, 9)]; return b('Matrices', `Transpose the matrix [${m.map(L).join(', ')}] and print the result as a list of lists.`, `m = [${m.map(L).join(', ')}]\nprint([list(row) for row in zip(*m)])`, 'zip(*m) swaps rows and columns.'); },
  (r) => { const m = [r.nums(3, 1, 9), r.nums(3, 1, 9), r.nums(3, 1, 9)]; return b('Matrices', `Print the sum of the main diagonal of [${m.map(L).join(', ')}].`, `m = [${m.map(L).join(', ')}]\nprint(sum(m[i][i] for i in range(3)))`, 'Diagonal cells are m[i][i].'); },
  (r) => { const a = r.nums(6, 1, 9), k = r.int(1, 4); return b('Rotation', `Rotate ${L(a)} to the left by ${k} positions and print the list.`, `nums = ${L(a)}\nprint(nums[${k}:] + nums[:${k}])`, 'Slice twice and join.'); },
  (r) => { const a = r.nums(8, 1, 6); return b('Deduplication', `Remove duplicates from ${L(a)} while keeping the first occurrence of each value in order. Print the list.`, `seen = []\nfor x in ${L(a)}:\n    if x not in seen:\n        seen.append(x)\nprint(seen)`, 'Check membership before appending.'); },
  (r) => { const s = r.pick(SENT); return b('Words', `Print the longest word in "${s}" (the first one wins a tie).`, `print(max("${s}".split(), key=len))`, 'max with key=len.'); },
  (r) => { const s = r.pick(['(())', '(()', '()()', ')(', '((()))', '(()))', '()(()', '(()())']); return b('Stacks', `Print True if the parentheses in "${s}" are balanced, otherwise False.`, `depth = 0\nok = True\nfor ch in "${s}":\n    depth += 1 if ch == "(" else -1\n    if depth < 0:\n        ok = False\nprint(ok and depth == 0)`, 'Never let the depth go negative; end at 0.'); },
  (r) => { const a = r.uniq(6, 1, 90); return b('Order statistics', `Print the second largest value in ${L(a)}.`, `print(sorted(${L(a)})[-2])`, 'Sort, then index from the end.'); },
  (r) => { const x = sorted9(r, 4), y = sorted9(r, 4); return b('Merging', `Merge the sorted lists ${L(x)} and ${L(y)} into one sorted list and print it.`, `print(sorted(${L(x)} + ${L(y)}))`, 'Combine, then sort.'); },
  (r) => { const a = r.nums(5, 1, 9); return b('Prefix sums', `Print the running (prefix) sums of ${L(a)} as a list.`, `total = 0\nout = []\nfor x in ${L(a)}:\n    total += x\n    out.append(total)\nprint(out)`, 'Add each value to a running total.'); },
  (r) => { const s = r.pick(SENT); return b('Frequency maps', `Count how many times each word occurs in "${s}" and print the dictionary.`, `counts = {}\nfor w in "${s}".split():\n    counts[w] = counts.get(w, 0) + 1\nprint(counts)`, 'Split, then count with get().'); },
  (r) => { const n = r.int(3, 8); return b('Pascal', `Print row ${n} (counting the top row as row 0) of Pascal's triangle as a list.`, `row = [1]\nfor _ in range(${n}):\n    row = [1] + [row[i] + row[i + 1] for i in range(len(row) - 1)] + [1]\nprint(row)`, 'Each inner value sums two neighbours above.'); },
  (r) => { const a = r.nums(7, 1, 9), t = r.int(7, 14); return b('Pairs', `Count the pairs (i < j) in ${L(a)} whose values add up to ${t} and print the count.`, `nums = ${L(a)}\ncount = 0\nfor i in range(len(nums)):\n    for j in range(i + 1, len(nums)):\n        if nums[i] + nums[j] == ${t}:\n            count += 1\nprint(count)`, 'Visit every pair once.'); },
];

/* ───────── Tier 10 · dynamic programming, graphs, itertools, closures ───────── */
const T10: Gen[] = [
  (r) => { const n = r.int(20, 60); return b('Memoization', `Compute fib(${n}) (fib(0)=0, fib(1)=1) with a dictionary cache so it finishes instantly, and print it.`, `memo = {}\ndef fib(n):\n    if n < 2:\n        return n\n    if n not in memo:\n        memo[n] = fib(n - 1) + fib(n - 2)\n    return memo[n]\nprint(fib(${n}))`, 'Store results by n.'); },
  (r) => { const coins = r.pick([[1, 5, 10], [1, 3, 4], [1, 2, 5], [2, 5, 6], [1, 6, 10]]), amt = r.int(11, 30); return b('Dynamic programming', `Print the fewest coins from ${L(coins)} (unlimited of each) that sum to ${amt}.`, `coins = ${L(coins)}\nbest = [0] + [999] * ${amt}\nfor a in range(1, ${amt + 1}):\n    for c in coins:\n        if c <= a:\n            best[a] = min(best[a], best[a - c] + 1)\nprint(best[${amt}])`, 'best[a] = min over coins of best[a - c] + 1.'); },
  (r) => { const a = r.nums(8, 1, 20); return b('Dynamic programming', `Print the length of the longest strictly increasing subsequence of ${L(a)}.`, `nums = ${L(a)}\nbest = [1] * len(nums)\nfor i in range(len(nums)):\n    for j in range(i):\n        if nums[j] < nums[i]:\n            best[i] = max(best[i], best[j] + 1)\nprint(max(best))`, 'best[i] extends the best earlier smaller value.'); },
  (r) => { const edges: Record<string, string[]> = { a: ['b', 'c'], b: ['d'], c: ['d', 'e'], d: ['f'], e: ['f'], f: [] }; const goal = r.pick(['d', 'e', 'f']); const g = `{${Object.entries(edges).map(([k, v]) => `"${k}": ${SL(v)}`).join(', ')}}`; return b('Graphs', `In the graph ${g}, print the fewest edges needed to travel from "a" to "${goal}" using breadth-first search.`, `graph = ${g}\nfrontier = ["a"]\ndist = {"a": 0}\nwhile frontier:\n    node = frontier.pop(0)\n    for nxt in graph[node]:\n        if nxt not in dist:\n            dist[nxt] = dist[node] + 1\n            frontier.append(nxt)\nprint(dist["${goal}"])`, 'BFS explores level by level.'); },
  (r) => { const w = r.pick(['abc', 'xyz', 'sun', 'cat', 'ore']); return b('itertools', `Print every ordering of the letters of "${w}" as a list of strings, in the order itertools.permutations produces them.`, `from itertools import permutations\nprint(["".join(p) for p in permutations("${w}")])`, 'permutations(iterable) yields tuples.'); },
  (r) => { const w = r.pick(['moon', 'star', 'dusk', 'wave', 'glow']), k = r.int(2, 3); return b('itertools', `Print every ${k}-letter combination of "${w}" as a list of strings, in the order itertools.combinations produces them.`, `from itertools import combinations\nprint(["".join(c) for c in combinations("${w}", ${k})])`, 'combinations(iterable, k).'); },
  (r) => { const k = r.int(2, 9), n = r.int(3, 20); return b('Closures', `Write make_multiplier(k) that returns a function multiplying its input by k. Print make_multiplier(${k})(${n}).`, `def make_multiplier(k):\n    def inner(x):\n        return x * k\n    return inner\nprint(make_multiplier(${k})(${n}))`, 'The inner function remembers k.'); },
  (r) => { const x = r.int(2, 12), k = r.int(2, 5); return b('Decorators', `Write a decorator scaled that multiplies a function's return value by ${k}. Decorate add(a, b) and print add(${x}, ${x + 1}).`, `def scaled(fn):\n    def wrapper(a, b):\n        return fn(a, b) * ${k}\n    return wrapper\n@scaled\ndef add(a, b):\n    return a + b\nprint(add(${x}, ${x + 1}))`, 'A decorator takes and returns a function.'); },
  (r) => { const ws = r.pick([['flower', 'flow', 'flight'], ['nebula', 'nebular', 'neon'], ['signal', 'sign', 'silver'], ['lumen', 'lumber', 'lump'], ['starfall', 'starlit', 'start']]); return b('Strings', `Print the longest common prefix of ${SL(ws)}.`, `words = ${SL(ws)}\nprefix = words[0]\nfor w in words[1:]:\n    while not w.startswith(prefix):\n        prefix = prefix[:-1]\nprint(prefix)`, 'Trim the prefix until every word starts with it.'); },
  (r) => { const n = r.int(5, 30); return b('Dynamic programming', `You climb stairs taking 1 or 2 steps at a time. Print how many distinct ways there are to climb ${n} steps.`, `a, b = 1, 1\nfor _ in range(${n} - 1):\n    a, b = b, a + b\nprint(b)`, 'ways(n) = ways(n-1) + ways(n-2).'); },
  (r) => { const a = r.nums(4, 4, 60).map((x) => x * 2); return b('reduce', `Use functools.reduce with math.gcd to print the greatest common divisor of all of ${L(a)}.`, `from functools import reduce\nfrom math import gcd\nprint(reduce(gcd, ${L(a)}))`, 'reduce folds a list with a two-argument function.'); },
  (r) => { const n = r.int(30, 150); return b('Sieve', `Use the Sieve of Eratosthenes to print how many primes are at most ${n}.`, `n = ${n}\nflags = [True] * (n + 1)\nflags[0] = flags[1] = False\nfor i in range(2, int(n ** 0.5) + 1):\n    if flags[i]:\n        for j in range(i * i, n + 1, i):\n            flags[j] = False\nprint(sum(flags))`, 'Cross out multiples of each prime.'); },
  (r) => { const a = [r.nums(2, 1, 5), r.nums(2, 1, 5)], c = [r.nums(2, 1, 5), r.nums(2, 1, 5)]; return b('Matrices', `Multiply the 2×2 matrices [${a.map(L).join(', ')}] and [${c.map(L).join(', ')}] and print the result as a list of lists.`, `a = [${a.map(L).join(', ')}]\nb = [${c.map(L).join(', ')}]\nprint([[sum(a[i][k] * b[k][j] for k in range(2)) for j in range(2)] for i in range(2)])`, 'Row of a times column of b.'); },
  (r) => { const grid = Array.from({ length: 4 }, () => Array.from({ length: 5 }, () => r.pick(['#', '.', '.']))); const rows = grid.map((x) => x.join('')); return b('Flood fill', `Count the islands (groups of "#" cells connected up, down, left or right) in the grid ${SL(rows)} and print the number.`, `grid = ${SL(rows)}\nseen = set()\ndef visit(r, c):\n    if r < 0 or c < 0 or r >= len(grid) or c >= len(grid[0]):\n        return\n    if grid[r][c] != "#" or (r, c) in seen:\n        return\n    seen.add((r, c))\n    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n        visit(r + dr, c + dc)\ncount = 0\nfor r in range(len(grid)):\n    for c in range(len(grid[0])):\n        if grid[r][c] == "#" and (r, c) not in seen:\n            count += 1\n            visit(r, c)\nprint(count)`, 'Depth-first search from each unseen "#".'); },
  (r) => { const n = r.pick([4, 9, 14, 29, 44, 49, 94, 99, 444, 1994, 2026, 1666, 3888, 1987]); return b('Roman numerals', `Print the Roman numeral for ${n}.`, `n = ${n}\nout = ""\nfor value, sym in [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]:\n    while n >= value:\n        out += sym\n        n -= value\nprint(out)`, 'Greedily subtract the largest symbol that fits.'); },
  (r) => { const n = r.int(5, 14), k = r.int(2, 5); return b('Josephus', `${n} people stand in a circle numbered 1 to ${n}. Starting at 1, every ${k}th person is removed until one is left. Print the survivor's number.`, `people = list(range(1, ${n + 1}))\ni = 0\nwhile len(people) > 1:\n    i = (i + ${k} - 1) % len(people)\n    people.pop(i)\nprint(people[0])`, 'Index arithmetic modulo the current length.'); },
  (r) => { const ns = r.uniq(4, 0, NAMES.length - 1).map((i) => NAMES[i]), sc = [r.int(50, 99), r.int(50, 99), r.int(50, 99), r.int(50, 99)]; sc[1] = sc[0]; const ps = ns.map((n, i) => `("${n}", ${sc[i]})`); return b('Multi-key sorting', `Sort the students [${ps.join(', ')}] by score (highest first), breaking ties alphabetically by name. Print the names in order, separated by spaces.`, `students = [${ps.join(', ')}]\nstudents.sort(key=lambda s: (-s[1], s[0]))\nprint(" ".join(s[0] for s in students))`, 'Sort by a tuple key.'); },
  (r) => { const bits = Array.from({ length: r.int(5, 8) }, () => r.pick(['0', '1'])).join(''); return b('Binary', `Convert the binary string "${bits}" to a decimal number without using int(x, 2) and print it.`, `bits = "${bits}"\nvalue = 0\nfor ch in bits:\n    value = value * 2 + int(ch)\nprint(value)`, 'Double the running value, then add the bit.'); },
];

const TIERS: Gen[][] = [T1, T2, T3, T4, T5, T6, T7, T8, T9, T10];
export const FAMILY_COUNT = TIERS.reduce((n, t) => n + t.length, 0);

const ADJ = ['Hollow','Silent','Pale','Velvet','Distant','Gilded','Drowned','Quiet','Fading','Wandering','Crystal','Ashen','Veiled','Restless','Silver','Midnight','Borrowed','Gentle','Forgotten','Luminous','Sable','Brittle','Tidal','Frozen','Burning','Secret','Lonely','Ember','Glass','Heavy','Slow','Winter','Mirrored','Thorned','Opal'];
const NOUN = ['Lantern','Signal','Harbor','Orbit','Compass','Cipher','Tide','Garden','Bridge','Echo','Comet','Archive','Engine','Crown','Mirror','Shore','Thread','Key','Window','Lighthouse','Anchor','Meadow','Clock','Feather','Ladder','Whisper','Ember','Atlas'];
export const titleFor = (i: number) => { const a = i % ADJ.length; return `${ADJ[a]} ${NOUN[(Math.floor(i / ADJ.length) + a) % NOUN.length]}`; };

/** Builds levels `from`…`to` (inclusive). Guarantees unique prompts and ≤ 20-line solutions. */
export function buildLevels(from: number, to: number, seen: Set<string> = new Set()): Array<Built & { id: number; tier: number }> {
  const out: Array<Built & { id: number; tier: number }> = [];
  const span = to - from + 1, perTier = Math.ceil(span / 10);
  for (let id = from; id <= to; id++) {
    const idx = id - from, tier = Math.min(10, Math.floor(idx / perTier) + 1), j = idx - (tier - 1) * perTier, fams = TIERS[tier - 1];
    const cycle = Math.floor(j / fams.length), order = fams.map((_, k) => k).sort((x, y) => ((x * 2654435761 + cycle * 40503 + tier) % 997) - ((y * 2654435761 + cycle * 40503 + tier) % 997));
    let made: Built | null = null;
    for (let attempt = 0; attempt < 400 && !made; attempt++) {
      const fam = fams[order[(j + Math.floor(attempt / 100)) % fams.length]];
      const cand = fam(rng(id * 7919 + attempt * 104729 + tier));
      if (!seen.has(cand.prompt) && cand.target.split('\n').length <= 20) made = cand;
    }
    if (!made) throw new Error(`Could not build a unique level ${id}`);
    seen.add(made.prompt);
    out.push({ ...made, id, tier });
  }
  return out;
}
